// Payment API on UTC+2, refund worker on UTC: both log DateTime.Now
var paidAt = new DateTime(2026, 11, 3, 10, 0, 0);    // 08:00 UTC
var refundedAt = new DateTime(2026, 11, 3, 8, 5, 0); // 08:05 UTC

if (refundedAt < paidAt)
{
    Console.WriteLine("Refund before payment!"); // fires, wrongly
}

Console.WriteLine(refundedAt - paidAt); // -01:55:00

// Each service records an instant: the time plus its UTC offset
var paidAt = new DateTimeOffset(2026, 11, 3, 10, 0, 0, TimeSpan.FromHours(2));
var refundedAt = new DateTimeOffset(2026, 11, 3, 8, 5, 0, TimeSpan.Zero);

if (refundedAt < paidAt)
{
    Console.WriteLine("Refund before payment!"); // never fires
}

Console.WriteLine(refundedAt - paidAt); // 00:05:00

