public sealed class RefundPolicy(TimeProvider clock)
{
    private static readonly TimeSpan Window = TimeSpan.FromDays(14);

    public bool CanRefund(DateTimeOffset paidAt) =>
        clock.GetUtcNow() - paidAt <= Window;
}

